from datetime import date, timedelta

_WD = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}


def recur(start: str, rule: str, count: int) -> list[str]:
    y, m, d = (int(p) for p in start.split("-"))
    start_d = date(y, m, d)
    parts = rule.split()
    kind = parts[0]
    k = int(parts[1])
    out: list[str] = []

    if kind == "DAILY":
        cur = start_d
        for _ in range(count):
            out.append(cur.isoformat())
            cur += timedelta(days=k)
        return out

    if kind == "WEEKLY":
        weekdays = sorted(_WD[token] for token in parts[2].split(","))
        monday = start_d - timedelta(days=start_d.weekday())
        week = 0
        while len(out) < count:
            for wd in weekdays:
                dt = monday + timedelta(days=week * 7 + wd)
                if dt >= start_d:
                    out.append(dt.isoformat())
                    if len(out) == count:
                        break
            week += k
        return out

    if kind == "YEARLY":
        mm, dd = (int(p) for p in parts[2].split("-"))
        year = start_d.year
        while len(out) < count:
            try:
                dt = date(year, mm, dd)
            except ValueError:
                year += k
                continue
            if dt >= start_d:
                out.append(dt.isoformat())
            year += k
        return out

    # MONTHLY
    base = start_d.year * 12 + (start_d.month - 1)
    step = 0
    if len(parts) == 3:
        day = int(parts[2])
        while len(out) < count:
            cy, cm0 = divmod(base + step, 12)
            cm = cm0 + 1
            step += k
            if day == -1:
                dt = date(cy + (cm == 12), 1 if cm == 12 else cm + 1, 1) - timedelta(days=1)
            else:
                try:
                    dt = date(cy, cm, day)
                except ValueError:
                    continue
            if dt >= start_d:
                out.append(dt.isoformat())
        return out

    n = int(parts[2])
    wd = _WD[parts[3]]
    while len(out) < count:
        cy, cm0 = divmod(base + step, 12)
        cm = cm0 + 1
        step += k
        first = date(cy, cm, 1)
        first_wd = first + timedelta(days=(wd - first.weekday()) % 7)
        if n == -1:
            dt = first_wd
            while (dt + timedelta(days=7)).month == cm:
                dt += timedelta(days=7)
        else:
            dt = first_wd + timedelta(days=7 * (n - 1))
            if dt.month != cm:
                continue
        if dt >= start_d:
            out.append(dt.isoformat())
    return out
